<script module lang="ts">
/**
 * Equal-track grid for card fields, stat rows and form pairs (`design/components/grid.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/grid.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { type Snippet } from 'svelte'

import {
  attributes,
  joinSlot,
  spacingAttrs,
  type LayoutPatch,
  type SpaceStep,
} from '@polymorph/svelte'
import styles from '@polymorph/recipes/layout/layout.module.css'

export type GridAlign = NonNullable<GridProps['align']>

export type GridColumns = NonNullable<GridProps['columns']>

export type GridElement = NonNullable<GridProps['as']>

export interface GridProps {
  align?: 'stretch' | 'start' | 'center' | 'end'
  as?: 'div' | 'section' | 'ul'
  children?: Snippet
  columns?: 1 | 2 | 3 | 4 | 6 | 12
  gap?: SpaceStep
  p?: SpaceStep
  patch?: LayoutPatch
  px?: SpaceStep
  py?: SpaceStep
}
</script>

<script lang="ts">
let {
  align = 'stretch',
  as = 'div',
  children,
  columns = 2,
  gap,
  p,
  patch,
  px,
  py,
}: GridProps = $props()
const joined = joinSlot(undefined, () => ({}))
</script>

{@render joined.start?.()
}{#if joined.shown
  }<svelte:element
    this={as}
    {...attributes(spacingAttrs({ gap, p, px, py, patch }))}
    class={[styles.layout, styles.grid]}
    data-columns={String(columns)}
    data-align={align}
    data-member="grid"
    >{@render children?.()
  }</svelte:element
>{/if
}{@render joined.end?.()}
